TLM.f("Tempora/Nat1-0",{"officium":"Dominica Infra Octavam Nativitatis","rule":["Gloria","Credo","Prefatio=Nat","no commemoratio (rubrica 1960)"],"ruleInherited":["celebranda aut missa prima aut missa secunda aut missa tertia"],"fallback":"Sancti/12-25","sections":{"Introitus":[{"k":"ref","la":"Sap 18:14-15"},{"k":"text","la":"Dum médium siléntium tenérent ómnia, et nox in suo cursu médium iter háberet, omnípotens Sermo tuus, Dómine, de cœlis a regálibus sédibus venit."},{"k":"ref","la":"Ps 92:1"},{"k":"text","la":"Dóminus regnávit, decórem indútus est: indútus est Dóminus fortitúdinem, et præcínxit se."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Dum médium siléntium tenérent ómnia, et nox in suo cursu médium iter háberet, omnípotens Sermo tuus, Dómine, de cœlis a regálibus sédibus venit."}],"Oratio":[{"k":"text","la":"Omnípotens sempitérne Deus, dírige actus nostros in beneplácito tuo: ut in nómine dilécti Fílii tui mereámur bonis opéribus abundáre:"},{"k":"macro","name":"Qui tecum"}],"Lectio":[{"k":"text","la":"Lectio Epístolæ beati Pauli Apóstoli ad Gálatas."},{"k":"ref","la":"Gal 4:1-7"},{"k":"text","la":"Fratres: Quanto témpore heres párvulus est, nihil differt a servo, cum sit dóminus ómnium: sed sub tutóribus et actóribus est usque ad præfinítum tempus a patre: ita et nos, cum essémus párvuli, sub eleméntis mundi erámus serviéntes. At ubi venit plenitúdo témporis, misit Deus Fílium suum, factum ex mulíere, factum sub lege, ut eos, qui sub lege erant, redímeret, ut adoptiónem filiórum reciperémus. Quóniam autem estis fílii, misit Deus Spíritum Fílii sui in corda vestra, clamántem: Abba, Pater. Itaque jam non est servus, sed fílius: quod si fílius, et heres per Deum."}],"Graduale":[{"k":"ref","la":"Ps 44:3; 44:2"},{"k":"text","la":"Speciósus forma præ filiis hóminum: diffúsa est gratia in lábiis tuis."},{"k":"text","la":"Eructávit cor meum verbum bonum, dico ego ópera mea Regi: lingua mea cálamus scribæ, velóciter scribéntis. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 92:1"},{"k":"text","la":"Dóminus regnávit, decórem índuit: índuit Dóminus fortitúdinem, et præcínxit se virtúte. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secundum Lucam."},{"k":"ref","la":"Luc 2:33-40"},{"k":"text","la":"In illo témpore: Erat Joseph et María Mater Jesu, mirántes super his quæ dicebántur de illo. Et benedíxit illis Símeon, et dixit ad Maríam Matrem ejus: Ecce, pósitus est hic in ruínam et in resurrectiónem multórum in Israël: et in signum, cui contradicétur: et tuam ipsíus ánimam pertransíbit gládius, ut reveléntur ex multis córdibus cogitatiónes. Et erat Anna prophetíssa, fília Phánuel, de tribu Aser: hæc procésserat in diébus multis, et víxerat cum viro suo annis septem a virginitáte sua. Et hæc vídua usque ad annos octogínta quátuor: quæ non discedébat de templo, jejúniis et obsecratiónibus sérviens nocte ac die. Et hæc, ipsa hora supervéniens, confitebátur Dómino, et loquebátur de illo ómnibus, qui exspectábant redemptiónem Israël. Et ut perfecérunt ómnia secúndum legem Dómini, revérsi sunt in Galilǽam in civitátem suam Názareth. Puer autem crescébat, et confortabátur, plenus sapiéntia: et grátia Dei erat in illo."}],"Offertorium":[{"k":"ref","la":"Ps 92:1-2"},{"k":"text","la":"Deus firmávit orbem terræ, qui non commovébitur: paráta sedes tua, Deus, ex tunc, a sǽculo tu es."}],"Secreta":[{"k":"text","la":"Concéde, quǽsumus, omnípotens Deus: ut óculis tuæ majestátis munus oblátum, et grátiam nobis piæ devotiónis obtineat, et efféctum beátæ perennitátis acquírat."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 2:20"},{"k":"text","la":"Tolle Púerum et Matrem ejus, et vade in terram Israël: defúncti sunt enim, qui quærébant ánimam Púeri."}],"Postcommunio":[{"k":"text","la":"Per hujus, Dómine, operatiónem mystérii, et vitia nostra purgéntur, et justa desidéria compleántur."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Oratio":[{"k":"rubric","la":"Pro Octava Nativitatis:"},{"k":"text","la":"Concéde, quǽsumus, omnípotens Deus: ut nos Unigéniti tui nova per carnem Natívitas líberet; quos sub peccáti jugo vetústa sérvitus tenet."},{"k":"macro","name":"Per eundem"}],"Commemoratio Secreta":[{"k":"rubric","la":"Pro Octava Nativitatis:"},{"k":"text","la":"Obláta, Dómine, múnera, nova Unigéniti tui Nativitáte sanctífica: nosque a peccatórum nostrórum máculis emúnda."},{"k":"macro","name":"Per eundem"}],"Commemoratio Postcommunio":[{"k":"rubric","la":"Pro Octava Nativitatis:"},{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut natus hódie Salvátor mundi, sicut divínæ nobis generatiónis est auctor; ita et immortalitátis sit ipse largítor:"},{"k":"macro","name":"Qui tecum"}]},"hr":{"fd30ca69fb0cc70e":{"t":"Mudr 18, 14-15, Ps 92, 1\n(Mudr 18, 14-15) Duboka šutnja obuzimaše sve i noć je bila u sredini svoga toka, kad je svemoguća tvoja Riječ, Gospodine, sišla s neba s kraljevskoga prijestolja. (Ps 92, 1) Gospodin kraljuje, ogrnuo se veličanstvom. Zaodio se Gospodin snagom i opasao se.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Mudr 18, 14-15) Duboka šutnja obuzimaše sve i noć je bila u sredini svoga toka, kad je svemoguća tvoja Riječ, Gospodine, sišla s neba s kraljevskoga prijestolja."},"adb813351b40ea37":{"t":"<i>Pomolimo se</i>.\nSvemogući vječni Bože, vodi naše čine da budu tebi mili, te zavrijedimo obilovati dobrim djelima u imenu ljubljenoga Sina tvoga:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"d22cf9278ab318f9":{"t":"Gal 4, 1-7\nČitanje Poslanice bl. Pavla apostola Galaćanima. Braćo: Dok je baštinik dijete, ni u čem se ne razlikuje od sluge, iako je gospodar svega. Nad njim ima vlast skrbnik i upravitelj sve do vremena što ga je odredio otac. Tako i mi, kad smo bili maleni, robovali smo načelima svijeta. Ali kad se ispunilo vrijeme, Bog je poslao svoga Sina koji se rodio od žene i podložio zakonu, da otkupi one pod zakonom te budemo posinjeni. Budući da ste sinovi, Bog je u vaša srca poslao Duha svojega Sina koji zove: »Abba–Oče!« Tako dakle više nisi sluga nego sin. Pa ako si sin, i Božji si baštinik."},"34b13b85db90ed1a":{"t":"Ps 44, 3 i 2\nNajljepši si od sinova ljudskih, ljupkost ti je razlivena na usnama. Iz mog srca vinula se dobra riječ. Svoja djela posvećujem kralju. Jezik je moj poput pera pisara.\n\nPs 92, 1\n<i>Aleluja</i>, <i>aleluja</i>.\nGospodin kraljuje, ogrnuo se veličanstvom. Zaodio se Gospodin snagom i opasao se jakošću. <i>Aleluja</i>."},"83d9938f5d819c04":{"t":"Lk 2, 33-40\nSlijedi sveto Evanđelje po Luki. U ono vrijeme čudili su se Josip i Marija, Isusova Majka, onome što se govorilo za njega. Šimun ih blagoslovi i reče Mariji, njegovoj Majci: »Evo, ovaj je postavljen na propast i na uskrsnuće mnogih u Izraelu i kao znak kome će se protiviti. A tebi će samoj mač probosti dušu, da se otkriju nakane mnogih srdaca.« – Bila je ondje i proročica, Fanuelova kći Ana, iz Aserova plemena, udovica u odmakloj dobi od osamdeset i četiri godine. U braku je od svog djevojaštva živjela sedam godina. Ona se nije udaljivala od hrama i služila je Bogu noć i dan postom i molitvom. Tada je i ona došla i slavila Gospodina te o njemu pripovijedala svima koji su očekivali Izraelovo otkupljenje. – I kad su izvršili sve propise Gospodnjega zakona, vrate se u Galileju u svoj grad Nazaret. Dijete je raslo i jačalo puno mudrosti te je na njemu bila Božja milost."},"04fc59c226e81717":{"t":"Ps 92, 1-2\nBog je učvrstio zemaljski krug. koji se neće pokolebati. Otada je pripravno prijestolje tvoje. Bože, Ti si od vijeka."},"901b65d1777a44c1":{"t":"Daj, molimo, svemogući Bože, da nam dar prinesen, pred oči tvoga veličanstva postigne milost prave pobožnosti i dobije nagradu blažene vječnosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"46276ff06c5f858a":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine sveti Oče, svemogući i vječni Bože: jer je po tajni utjelovljene Riječi očima naše duše sinula nova svjetlost tvoga sjaja. Te dok tjelesnim očima spoznajemo Boga, on nas zanosi ljubavlju prema nevidljivim dobrima. I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:"},"2219616f96606306":{"t":"Mt 2, 20\nUzmi Dječaka i njegovu Majku i idi u izraelsku zemlju, jer su umrli koji su tražili Dječakov život."},"1acbcdbc746602b4":{"t":"<i>Pomolimo se</i>.\nDjelovanjem ovoga otajstva, Gospodine, neka se očiste naše opačine i ispune pravedne želje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
